#include "espscreen/protocol/cobs.hpp"
namespace espscreen::protocol {
CodecResult cobs_encode(std::span<const std::uint8_t> in,std::span<std::uint8_t> out){if(out.empty())return {{core::ErrorCode::capacity_exceeded,"cobs output empty"},0};std::size_t read=0,write=1,code_index=0;std::uint8_t code=1;while(read<in.size()){if(in[read]==0){if(code_index>=out.size())return {{core::ErrorCode::capacity_exceeded,"cobs output too small"},0};out[code_index]=code;code=1;code_index=write++;++read;}else{if(write>=out.size())return {{core::ErrorCode::capacity_exceeded,"cobs output too small"},0};out[write++]=in[read++];if(++code==0xFF){if(code_index>=out.size())return {{core::ErrorCode::capacity_exceeded,"cobs output too small"},0};out[code_index]=code;code=1;code_index=write++;}}}if(code_index>=out.size())return {{core::ErrorCode::capacity_exceeded,"cobs output too small"},0};out[code_index]=code;return {core::Status::success(),write};}
CodecResult cobs_decode(std::span<const std::uint8_t> in,std::span<std::uint8_t> out){std::size_t read=0,write=0;while(read<in.size()){std::uint8_t code=in[read++];if(code==0)return {{core::ErrorCode::corrupt,"zero code in cobs frame"},0};for(std::uint8_t i=1;i<code;++i){if(read>=in.size())return {{core::ErrorCode::corrupt,"truncated cobs frame"},0};if(write>=out.size())return {{core::ErrorCode::capacity_exceeded,"cobs output too small"},0};out[write++]=in[read++];}if(code!=0xFF&&read<in.size()){if(write>=out.size())return {{core::ErrorCode::capacity_exceeded,"cobs output too small"},0};out[write++]=0;}}return {core::Status::success(),write};}
}
